     1	//! Which insured item a reported damage is a claim against.
     2	//!
     3	//! This is the office's matching rule, and it is a policy decision of its own:
     4	//! the MHPCO has to decide what a damage report names when a policy covers
     5	//! several items, and today it reads an `itemType` as naming the cover of that
     6	//! type the policy carries. It changes when the office revises how a report is
     7	//! read against a policy -- matching successive reports of one type to
     8	//! successive covers, refusing more reports of a type than the policy covers --
     9	//! independently of the clauses that then judge each damage's amount, and
    10	//! independently of the ceiling on what the settlement may total.
    11	
    12	use crate::{Damage, Item};
    13	
    14	/// The insured item a reported damage is matched to, if the policy covers one.
    15	///
    16	/// The MHPCO matches by item type alone: a report names a type, and the office
    17	/// looks for that type among the covers on the policy.
    18	pub(crate) fn matched_cover<'a>(insured: &'a [Item], damage: &Damage) -> Option<&'a Item> {
    19	    insured
    20	        .iter()
    21	        .find(|item| item.item_type == damage.item_type)
    22	}
===== src/pricing.rs =====
     1	//! The MHPCO price list: what each insurable item costs to cover, before any
     2	//! risk assessment or customer standing is taken into account.
     3	//!
     4	//! This is the catalog side of the office's knowledge. It changes when the
     5	//! MHPCO revises its prices or its building-block offer, independently of the
     6	//! underwriting rules that surcharge and discount a policy.
     7	
     8	use std::collections::BTreeMap;
     9	
    10	use crate::Item;
    11	
    12	const COMPONENT_BLOCK_SIZE: usize = 3;
    13	const COMPONENT_BLOCK_BASE_PREMIUM: f64 = 60.0;
    14	
    15	/// One entry in the MHPCO price list: what an item of this kind costs to
    16	/// cover, and what the office insures it for. The two travel together because
    17	/// they are one row of the list -- the office revises a price-list entry as a
    18	/// whole -- and because the kind decides how the item is priced in a policy.
    19	struct Listing {
    20	    base_premium: f64,
    21	    insurance_value: i64,
    22	    /// Components are the small insurable parts the MHPCO lists apart from
    23	    /// main items: they are priced per component and may form building blocks.
    24	    is_component: bool,
    25	}
    26	
    27	const SWORD: Listing = Listing {
    28	    base_premium: 100.0,
    29	    insurance_value: 1000,
    30	    is_component: false,
    31	};
    32	const AMULET: Listing = Listing {
    33	    base_premium: 60.0,
    34	    insurance_value: 600,
    35	    is_component: false,
    36	};
    37	const STAFF: Listing = Listing {
    38	    base_premium: 80.0,
    39	    insurance_value: 800,
    40	    is_component: false,
    41	};
    42	const POTION: Listing = Listing {
    43	    base_premium: 40.0,
    44	    insurance_value: 400,
    45	    is_component: false,
    46	};
    47	const COMPONENT: Listing = Listing {
    48	    base_premium: 25.0,
    49	    insurance_value: 250,
    50	    is_component: true,
    51	};
    52	
    53	/// The item's entry in the MHPCO price list, if the office lists its type at
    54	/// all. An item type the list does not name is not insurable.
    55	fn listed(item: &Item) -> Option<&'static Listing> {
    56	    match item.item_type.as_str() {
    57	        "sword" => Some(&SWORD),
    58	        "amulet" => Some(&AMULET),
    59	        "staff" => Some(&STAFF),
    60	        "potion" => Some(&POTION),
    61	        "rune" | "moonstone" => Some(&COMPONENT),
    62	        _ => None,
    63	    }
    64	}
    65	
    66	/// Whether the MHPCO lists this item type at all.
    67	pub(crate) fn is_listed(item: &Item) -> bool {
    68	    listed(item).is_some()
    69	}
    70	
    71	/// The item's entry in the MHPCO price list. Pricing is only ever asked of
    72	/// items the office has already accepted as listed, so an unlisted type
    73	/// cannot reach here; the office has no price to fall back on if one did.
    74	fn listing_for(item: &Item) -> &'static Listing {
    75	    listed(item).expect("the office prices only items it lists")
    76	}
    77	
    78	fn is_component(item: &Item) -> bool {
    79	    listing_for(item).is_component
    80	}
    81	
    82	/// A building block of alike components is offered at a special base premium.
    83	fn component_group_base_premium(count: usize) -> f64 {
    84	    if count == COMPONENT_BLOCK_SIZE {
    85	        COMPONENT_BLOCK_BASE_PREMIUM
    86	    } else {
    87	        count as f64 * COMPONENT.base_premium
    88	    }
    89	}
    90	
    91	/// Components are alike when they are of the very same type: the MHPCO reads
    92	/// "3 alike components" strictly, so runes and moonstones never share a block.
    93	fn alike_component_kind(item: &Item) -> &str {
    94	    item.item_type.as_str()
    95	}
    96	
    97	/// The base premium of all components in a policy: components of the same kind
    98	/// are counted together so that their building block can apply.
    99	fn components_base_premium(items: &[Item]) -> f64 {
   100	    let mut counts: BTreeMap<&str, usize> = BTreeMap::new();
   101	    for item in items.iter().filter(|item| is_component(item)) {
   102	        *counts.entry(alike_component_kind(item)).or_default() += 1;
   103	    }
   104	    counts.into_values().map(component_group_base_premium).sum()
   105	}
   106	
   107	/// The base premium of all main items in a policy, straight from the price list.
   108	fn main_items_base_premium(items: &[Item]) -> f64 {
   109	    items
   110	        .iter()
   111	        .filter(|item| !is_component(item))
   112	        .map(|item| listing_for(item).base_premium)
   113	        .sum()
   114	}
   115	
   116	/// The policy base premium: the sum of the base premiums of all insured items.
   117	pub(crate) fn policy_base_premium(items: &[Item]) -> f64 {
   118	    main_items_base_premium(items) + components_base_premium(items)
   119	}
   120	
   121	/// The base premium an item-specific modifier is measured against: the item's
   122	/// own listed price, which for a component is the per-component premium.
   123	pub(crate) fn item_base_premium(item: &Item) -> f64 {
   124	    listing_for(item).base_premium
   125	}
   126	
   127	/// The insurance sum of a policy: the sum of its items' insurance values.
   128	/// Unlike the premium, the insurance sum knows nothing of building blocks --
   129	/// three alike components are insured for three times a component's value.
   130	pub(crate) fn insurance_sum(items: &[Item]) -> i64 {
   131	    items
   132	        .iter()
   133	        .map(|item| listing_for(item).insurance_value)
   134	        .sum()
   135	}
===== src/reimbursement.rs =====
     1	//! What the MHPCO reimburses for a single reported damage: the clauses the
     2	//! office applies to one damage amount before it reaches the settlement.
     3	//!
     4	//! This is the claim side's judgement of a single damage event. It changes
     5	//! when the office revises its clauses -- a steeper deductible, a new
     6	//! material that is fully covered, a different enchantment level -- quite
     7	//! independently of the policy-wide limits on what a settlement may total,
     8	//! and independently of how the premium side assessed the same item's risk.
     9	
    10	use crate::{Damage, Item};
    11	
    12	/// A deductible applies per damage event.
    13	const DEDUCTIBLE: f64 = 100.0;
    14	
    15	/// Damage to an item enchanted at this level or above is reimbursed at half.
    16	const HALF_REIMBURSEMENT_LEVEL: i64 = 8;
    17	
    18	/// The share of the damage that clause reimburses.
    19	const HALF_REIMBURSEMENT_SHARE: f64 = 0.5;
    20	
    21	/// With no clause cutting it down, the MHPCO reimburses a damage in full.
    22	const FULL_REIMBURSEMENT_SHARE: f64 = 1.0;
    23	
    24	/// Whether the half-reimbursement clause applies to an insured item. The claim
    25	/// side judges high enchantment by its own level, well above the one the
    26	/// premium side surcharges for.
    27	fn half_reimbursement_applies(item: &Item) -> bool {
    28	    item.enchantment >= HALF_REIMBURSEMENT_LEVEL
    29	}
    30	
    31	/// Which share of a reported damage the office's clauses cover. The MHPCO
    32	/// reimburses in full unless a clause of its own cuts the share down, and a
    33	/// damage to no recognised item meets no clause at all.
    34	fn reimbursement_share(damaged: Option<&Item>) -> f64 {
    35	    if damaged.is_some_and(half_reimbursement_applies) {
    36	        HALF_REIMBURSEMENT_SHARE
    37	    } else {
    38	        FULL_REIMBURSEMENT_SHARE
    39	    }
    40	}
    41	
    42	/// How much of a reported damage the office covers, before the deductible.
    43	fn covered_amount(damage: &Damage, damaged: Option<&Item>) -> f64 {
    44	    damage.amount as f64 * reimbursement_share(damaged)
    45	}
    46	
    47	/// What the MHPCO reimburses for one reported damage: the share of the
    48	/// damage the office covers, less the deductible the claimant bears
    49	/// themselves.
    50	///
    51	/// The amount is carried as a fraction: the MHPCO keeps intermediate amounts
    52	/// unrounded and rounds only the settlement the claimant is finally paid.
    53	pub(crate) fn damage_reimbursement(damage: &Damage, damaged: Option<&Item>) -> f64 {
    54	    covered_amount(damage, damaged) - DEDUCTIBLE
    55	}
===== src/risk.rs =====
     1	//! The MHPCO's risk assessment of a single insured item: which properties of
     2	//! an item the office judges hazardous, and what surcharge each one carries.
     3	//!
     4	//! This is the underwriting side's view of an item's danger. It changes when
     5	//! the office revises its risk appetite -- a steeper curse surcharge, a new
     6	//! hazardous property -- independently of the customer's standing, of the
     7	//! price list, and of how a claim later judges the same item.
     8	
     9	use crate::pricing::item_base_premium;
    10	use crate::Item;
    11	
    12	const CURSE_SURCHARGE: f64 = 0.50;
    13	const HIGH_ENCHANTMENT_SURCHARGE: f64 = 0.30;
    14	const HIGH_ENCHANTMENT_LEVEL: i64 = 5;
    15	
    16	/// An item counts as highly enchanted for the premium's risk assessment from
    17	/// the MHPCO's listed enchantment level upwards. The claim side judges high
    18	/// enchantment by its own, separate level.
    19	fn is_highly_enchanted(item: &Item) -> bool {
    20	    item.enchantment >= HIGH_ENCHANTMENT_LEVEL
    21	}
    22	
    23	/// The risk surcharge rate a single item carries, as a share of its own base
    24	/// premium: the MHPCO's item-specific risk assessment.
    25	fn item_surcharge_rate(item: &Item) -> f64 {
    26	    let mut rate = 0.0;
    27	    if item.cursed {
    28	        rate += CURSE_SURCHARGE;
    29	    }
    30	    if is_highly_enchanted(item) {
    31	        rate += HIGH_ENCHANTMENT_SURCHARGE;
    32	    }
    33	    rate
    34	}
    35	
    36	/// What the policy's hazardous items add to its premium: each affected item
    37	/// surcharges its own base premium, never the rest of the policy.
    38	pub(crate) fn item_risk_surcharges(items: &[Item]) -> f64 {
    39	    items
    40	        .iter()
    41	        .map(|item| item_base_premium(item) * item_surcharge_rate(item))
    42	        .sum()
    43	}
===== src/settlement_limit.rs =====
     1	//! The ceiling the MHPCO puts on what a policy will ever pay out, and how far
     2	//! a policy has already eaten into it.
     3	//!
     4	//! This is the office's exposure limit. It changes when the MHPCO revises how
     5	//! far it will stand behind a policy -- a different multiple of the insurance
     6	//! sum, a different basis for that sum, a ceiling that resets with the
     7	//! insurance year rather than running for the life of the policy -- and those
     8	//! revisions change together, because the ceiling and the running total
     9	//! measured against it are one piece of knowledge. It changes independently of
    10	//! the clauses that judge any single damage, and independently of how the
    11	//! premium side surcharged the same items: premium modifiers never raise the
    12	//! cap.
    13	
    14	use crate::pricing::insurance_sum;
    15	use crate::{Item, Settlement};
    16	
    17	/// The total payout per policy is capped at twice its insurance sum.
    18	const CAP_MULTIPLE: i64 = 2;
    19	
    20	/// How far a policy has eaten into the most the MHPCO will ever pay on it.
    21	///
    22	/// The ceiling covers the policy rather than any one claim, so the office
    23	/// carries this from settlement to settlement: each claim is paid out of
    24	/// what successive earlier ones have left.
    25	pub(crate) struct PolicyExposure {
    26	    remaining: i64,
    27	}
    28	
    29	impl PolicyExposure {
    30	    /// A policy's exposure at the outset: the whole ceiling is still available.
    31	    pub(crate) fn on_policy_covering(items: &[Item]) -> Self {
    32	        PolicyExposure {
    33	            remaining: CAP_MULTIPLE * insurance_sum(items),
    34	        }
    35	    }
    36	
    37	    /// What the office actually settles once its exposure limit is applied to
    38	    /// the amount the claim's clauses would otherwise pay, spending that much
    39	    /// of the ceiling. The MHPCO does not refuse a claim that outruns the cap;
    40	    /// it pays up to what is left and reports how much exposure remains.
    41	    pub(crate) fn settle(&mut self, desired_payout: i64) -> Settlement {
    42	        let payout = desired_payout.min(self.remaining);
    43	        self.remaining -= payout;
    44	        Settlement {
    45	            payout,
    46	            remaining_cap: self.remaining,
    47	        }
    48	    }
    49	}
===== src/standing.rs =====
     1	//! How a customer's standing with the MHPCO bears on the premium: the
     2	//! policy-wide modifiers the office grants or levies for loyalty, for a first
     3	//! insurance, and for a contract that follows an earlier one.
     4	//!
     5	//! This is the customer-relations side of the office's knowledge. It changes
     6	//! when the MHPCO courts or squeezes its customers -- a longer loyalty
     7	//! qualification, a deeper follow-up discount -- independently of how
     8	//! hazardous any insured item happens to be.
     9	
    10	use crate::Customer;
    11	
    12	const FIRST_INSURANCE_SURCHARGE: f64 = 0.10;
    13	const LOYALTY_DISCOUNT: f64 = 0.20;
    14	const LOYALTY_YEARS: i64 = 2;
    15	const FOLLOW_UP_CONTRACT_DISCOUNT: f64 = 0.15;
    16	
    17	/// A long-standing customer has been with the MHPCO for at least two years.
    18	fn is_long_standing(customer: &Customer) -> bool {
    19	    customer.years_with_mhpco >= LOYALTY_YEARS
    20	}
    21	
    22	/// Long-standing customers are rewarded with a discount on the policy.
    23	fn loyalty_rate(customer: &Customer) -> f64 {
    24	    if is_long_standing(customer) {
    25	        -LOYALTY_DISCOUNT
    26	    } else {
    27	        0.0
    28	    }
    29	}
    30	
    31	/// Every contract after the customer's first is discounted.
    32	fn follow_up_contract_rate(previous_quotes: usize) -> f64 {
    33	    if previous_quotes > 0 {
    34	        -FOLLOW_UP_CONTRACT_DISCOUNT
    35	    } else {
    36	        0.0
    37	    }
    38	}
    39	
    40	/// Every quote insures its items for the first time, so the initial assessment
    41	/// surcharge is carried unconditionally: the MHPCO reads "first insurance" as
    42	/// the item's, not the customer's, so customer history never waives it.
    43	fn first_insurance_rate() -> f64 {
    44	    FIRST_INSURANCE_SURCHARGE
    45	}
    46	
    47	/// The net policy-wide modifier rate the customer's circumstances carry, as a
    48	/// share of the policy base premium. The MHPCO sums its policy-wide modifiers
    49	/// rather than compounding them, so each one contributes its own rate here.
    50	fn policy_modifier_rate(customer: &Customer, previous_quotes: usize) -> f64 {
    51	    first_insurance_rate() + loyalty_rate(customer) + follow_up_contract_rate(previous_quotes)
    52	}
    53	
    54	/// What the customer's standing adds to or takes off the policy base premium.
    55	pub(crate) fn standing_adjustment(
    56	    base: f64,
    57	    customer: &Customer,
    58	    previous_quotes: usize,
    59	) -> f64 {
    60	    base * policy_modifier_rate(customer, previous_quotes)
    61	}

