  9	use pricing::{is_listed, policy_base_premium};
 10	use reimbursement::damage_reimbursement;
 11	use risk::item_risk_surcharges;
 12	use settlement_limit::PolicyExposure;
 13	use standing::standing_adjustment;
 14	
 15	pub struct Customer {
 16	    pub years_with_mhpco: i64,
 17	}
 18	
 19	pub struct Item {
 20	    pub item_type: String,
 21	    pub material: String,
 22	    pub cursed: bool,
 23	    pub enchantment: i64,
 24	}
 25	
 26	const PROCESSING_FEE: i64 = 5;
 27	
 28	pub struct Damage {
 29	    pub item_type: String,
 30	    pub amount: i64,
 31	}
 32	
 33	pub struct Settlement {
 34	    pub payout: i64,
 35	    pub remaining_cap: i64,
 36	}
 37	
 38	pub struct Policy<'a> {
 39	    insured: &'a [Item],
 40	    exposure: PolicyExposure,
 41	}
 42	
 43	impl<'a> Policy<'a> {
 44	    pub fn insuring(items: &'a [Item]) -> Self {
 45	        Policy {
 46	            insured: items,
 47	            exposure: PolicyExposure::on_policy_covering(items),
 48	        }
 49	    }
 50	
 51	    /// What the office settles for an incident: the clauses reimburse each
 52	    /// damage reported, and the policy's remaining exposure decides how much
 53	    /// of that total is actually paid.
 54	    pub fn claim(&mut self, damages: &[Damage]) -> Result<Settlement, Refusal> {
 55	        if let Some(refusal) = refusal_to_settle(self.insured, damages) {
 56	            return Err(refusal);
 57	        }
 58	        let reimbursed = self.incident_reimbursement(damages);
 59	        Ok(self
 60	            .exposure
 61	            .settle(round_payout_in_mhpco_favor(reimbursed)))
 62	    }
 63	
 64	    /// What the office's clauses reimburse for an incident, before its
 65	    /// exposure limit is brought to bear: every damage the incident reported,
 66	    /// each judged against the cover it names.
 67	    fn incident_reimbursement(&self, damages: &[Damage]) -> f64 {
 68	        damages
 69	            .iter()
 70	            .map(|damage| damage_reimbursement(damage, matched_cover(self.insured, damage)))
 71	            .sum()
 72	    }
 73	}
 74	
 75	/// A premium is rounded in the MHPCO's favor, which for money the customer
 76	/// owes the office means upwards.
 77	fn round_premium_in_mhpco_favor(premium: f64) -> i64 {
 78	    premium.ceil() as i64
 79	}
 80	
 81	/// A payout is rounded in the MHPCO's favor, which for money the office owes
 82	/// the claimant means downwards. Only the settlement total is rounded; the
 83	/// reimbursements it sums are carried as fractions.
 84	fn round_payout_in_mhpco_favor(payout: f64) -> i64 {
 85	    payout.floor() as i64
 86	}
 87	
 88	/// How the MHPCO's two kinds of modifier reach the premium: policy-wide
 89	/// modifiers scale the policy base premium, while item-specific modifiers are
 90	/// measured against their own item's base premium and are added alongside, so
 91	/// a curse never surcharges the rest of the policy.
 92	fn premium_before_fee(customer: &Customer, items: &[Item], previous_quotes: usize) -> f64 {
 93	    let base = policy_base_premium(items);
 94	    base + standing_adjustment(base, customer, previous_quotes) + item_risk_surcharges(items)
 95	}
 96	
 97	/// The MHPCO refuses business it has no rule for.
 98	#[derive(Debug, PartialEq, Eq)]
 99	pub enum Refusal {
100	    UnlistedItemType(String),
101	    UninsuredItemType(String),
102	}
103	
104	/// Why the office would refuse to insure this list of items, if it would.
105	/// Acceptance is settled before any pricing: the office only quotes business
106	/// its rules cover, and it names the first item it cannot place.
107	fn refusal_to_insure(items: &[Item]) -> Option<Refusal> {
108	    items
109	        .iter()
110	        .find(|item| !is_listed(item))
111	        .map(|unlisted| Refusal::UnlistedItemType(unlisted.item_type.clone()))
112	}
113	
114	/// Why the office would refuse to settle this incident against these covers,
115	/// if it would. Admissibility is settled before any clause is applied: the
116	/// office only entertains damage reported against cover the policy carries,
117	/// and it names the first damage it cannot place.
118	fn refusal_to_settle(insured: &[Item], damages: &[Damage]) -> Option<Refusal> {
119	    damages
120	        .iter()
121	        .find(|damage| matched_cover(insured, damage).is_none())
122	        .map(|uninsured| Refusal::UninsuredItemType(uninsured.item_type.clone()))
123	}
124	
125	pub fn quote(
126	    customer: &Customer,
127	    items: &[Item],
128	    previous_quotes: usize,
129	) -> Result<i64, Refusal> {
130	    if let Some(refusal) = refusal_to_insure(items) {
131	        return Err(refusal);
132	    }
133	    let premium = premium_before_fee(customer, items, previous_quotes);
134	    Ok(round_premium_in_mhpco_favor(premium) + PROCESSING_FEE)
135	}
